        children: "import { cert } from '@kit.DeviceCertificateKit';\nimport { BusinessError } from '@kit.BasicServicesKit';\n\n// string转Uint8Array。\nfunction stringToUint8Array(str: string): Uint8Array {\n  let arr: Array<number> = [];\n  for (let i = 0, j = str.length; i < j; i++) {\n    arr.push(str.charCodeAt(i));\n  }\n  return new Uint8Array(arr);\n}\n\nasync function createX509Cert(): Promise<cert.X509Cert> {\n  let certData = '-----BEGIN CERTIFICATE-----\\n' +\n    'MIIBHTCBwwICA+gwCgYIKoZIzj0EAwIwGjEYMBYGA1UEAwwPRXhhbXBsZSBSb290\\n' +\n    'IENBMB4XDTIzMDkwNTAyNDgyMloXDTI2MDUzMTAyNDgyMlowGjEYMBYGA1UEAwwP\\n' +\n    'RXhhbXBsZSBSb290IENBMFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEHjG74yMI\\n' +\n    'ueO7z3T+dyuEIrhxTg2fqgeNB3SGfsIXlsiUfLTatUsU0i/sePnrKglj2H8Abbx9\\n' +\n    'PK0tsW/VgqwDIDAKBggqhkjOPQQDAgNJADBGAiEApVZno/Z7WyDc/muRN1y57uaY\\n' +\n    'Mjrgnvp/AMdE8qmFiDwCIQCrIYdHVO1awaPgcdALZY+uLQi6mEs/oMJLUcmaag3E\\n' +\n    'Qw==\\n' +\n    '-----END CERTIFICATE-----\\n';\n\n  // 证书二进制数据，需业务自行赋值。\n  let encodingBlob: cert.EncodingBlob = {\n    data: stringToUint8Array(certData),\n    // 根据encodingData的格式进行赋值，支持FORMAT_PEM和FORMAT_DER。\n    encodingFormat: cert.EncodingFormat.FORMAT_PEM\n  };\n\n  let x509Cert: cert.X509Cert = {} as cert.X509Cert;\n  try {\n    x509Cert = await cert.createX509Cert(encodingBlob);\n  } catch (error) {\n    let e: BusinessError = error as BusinessError;\n    console.error(`createX509Cert failed, errCode: ${e.code}, errMsg: ${e.message}`);\n  }\n  return x509Cert;\n}\n\nasync function createX509CertChain(): Promise<cert.X509CertChain> {\n  const x509Cert = await createX509Cert();\n  let x509CertChain: cert.X509CertChain = {} as cert.X509CertChain;\n  try {\n    x509CertChain = cert.createX509CertChain([x509Cert]);\n  } catch (error) {\n    let e: BusinessError = error as BusinessError;\n    console.error(`createX509CertChain failed, errCode: ${e.code}, errMsg: ${e.message}`);\n  }\n  return x509CertChain;\n}\n\ncreateX509CertChain();\n"
